use super::*;


fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn decode<T:semio_framework_value::FromValue>(v:&serde_json::Value)->T{semio_framework_pack_json::from_json_str(&v.to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap()}
#[test]
fn original_reference_metadata_and_aliases_validate_without_drawing_materialization(){let f:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in f["cases"].as_array().unwrap(){for body in[17,256,1024]{for cut in[usize::MAX,0,1,7,80,600]{let mut native=f["base"].clone();if let Some(member)=row.get("documentMember"){native["backgroundDrawing"]=member.clone()}if let Some(members)=row["pageMembers"].as_array(){for member in members{let page=member["page"].as_u64().unwrap()as usize;native["pages"][page]["backgroundDrawing"]=member["member"].clone()}}let mut original=decode::<LayoutSnapshot>(&native);if let Some(a)=row.get("alter"){let h=&mut original.background_drawing.as_mut().unwrap().handle;let value=a["value"].as_str().unwrap().to_owned();match a["field"].as_str().unwrap(){"childId"=>h.child_id=value,"artifactId"=>h.target.artifact_id=value,"artifactKind"=>h.target.dialect.artifact_kind=value,"standard"=>h.target.dialect.standard=value,"subset"=>h.target.dialect.subset=value,_=>panic!("neutral reference field")}}assert_eq!(super::super::validate_document(&original).is_ok(),row["valid"].as_bool().unwrap());let mut original=FixtureSource::from_owner(original);let mut owner=LayoutValidationCursor::new();let mut done=false;for _ in 0..cut{let d=owner.demand(original.borrow(),body).unwrap();let g=grant(d);let turn=original_turn(g,|step|step.progress,|effect|owner.advance(original.borrow(),body,effect)).unwrap();let(a,e)=(turn.done,turn.error);if a{assert_eq!(e.is_none(),row["valid"].as_bool().unwrap());done=true;break}}if cut==usize::MAX{assert!(done)}owner.begin_close();while !owner.terminal_is_empty(){let d=owner.close_demand(body).unwrap();let g=grant(d);original_turn(g,|step:&RetainedCloneStep|step.progress(),|effect|owner.close_step(body,effect)).unwrap();}while !original.terminal_is_empty(){original.close_once().unwrap();}}}}}
